        void ScriptA4Lilly::a4_lilly() {
            if (ks::globals::exit_scenario) return;
            SKIP_IF_LOAD_ANOTHER_SCENE(SCRIPT_A4_LILLY);
            ks::SceneManager::set_script(SCRIPT_A4_LILLY);
            ks::SceneManager::init_savedata(ks::progress);
            ks::SceneManager::set(ks::SceneManager("script_a4_lilly"));
        
            ScriptA4Lilly::a4_lilly_slow_steps(); // INLINE CALL
            ks::SceneManager::timeskip();
            ScriptA4Lilly::a4_lilly_pajamas_and_suits(); // INLINE CALL
            ks::SceneManager::timeskip();
            ScriptA4Lilly::a4_lilly_correct_procedure(); // INLINE CALL
            ks::SceneManager::timeskip();
            ScriptA4Lilly::a4_lilly_out_and_about(); // INLINE CALL
            ks::SceneManager::timeskip();
            ScriptA4Lilly::a4_lilly_a_mornings_reverse(); // INLINE CALL
            ks::SceneManager::timeskip();
            ScriptA4Lilly::a4_lilly_blackout(); // INLINE CALL
            ks::SceneManager::timeskip();
            ScriptA4Lilly::a4_lilly_context(); // INLINE CALL
            ks::SceneManager::timeskip();
            ScriptA4Lilly::a4_lilly_a_faraway_future(); // INLINE CALL
            ks::SceneManager::timeskip();
            ScriptA4Lilly::a4_lilly_farewell(); // INLINE CALL
            if (!(ks::progress.want_true && ks::progress.address_it && ks::progress.mention_the_letter)) {
                // ach("lillyneutral_achieve"); TODO: unknown assignment
                return;
            }
            ks::SceneManager::timeskip();
            ScriptA4Lilly::a4_lilly_false_cadence(); // INLINE CALL
            ks::SceneManager::timeskip();
            ScriptA4Lilly::a4_lilly_under_a_maudlin_sky(); // INLINE CALL
            ScriptA4Lilly::a4_lilly_under_a_bright_sky(); // INLINE CALL
            ScriptA4Lilly::a4_lilly_forwards(); // INLINE CALL
        }
